package com.example.demo.adapters.jdbc;

import com.example.demo.application.commands.RegisterPersonCommand;
import com.example.demo.domain.Person;
import com.example.demo.domain.TimeOrderedUuid;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class JdbcRegisterPersonCommand implements RegisterPersonCommand {

    private final JdbcClient jdbc;

    public JdbcRegisterPersonCommand(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Person execute(RegisterPersonCommand.Input input) {
        JdbcClient.StatementSpec statement = jdbc.sql("insert into people (id, email) values (:id, :email) returning id, email, created_at");
        statement = statement.param("id", TimeOrderedUuid.next());
        statement = statement.param("email", input.email());
        return statement.query(Person.class).single();
    }
}
